using System.Security.Claims;using Kaluz.Web.Models;using Kaluz.Web.Services;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;
namespace Kaluz.Web.Controllers;
[Authorize(Roles="Administrador")]public class ComprasController(Db db,KaluzService svc):Controller{
 int U=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 public IActionResult Index(){ViewBag.Rows=db.List("SELECT TOP 120 c.*,p.Nombre Proveedor FROM Compra c JOIN Proveedor p ON p.IdProveedor=c.IdProveedor ORDER BY c.IdCompra DESC");return View();}
 [HttpGet]public IActionResult Crear(){ViewBag.Proveedores=db.List("SELECT IdProveedor,Nombre FROM Proveedor WHERE Activo=1");ViewBag.Variantes=db.List("SELECT v.IdVariante,p.Nombre+' / '+v.Talla+' / '+v.Color AS Nombre FROM ProductoVariante v JOIN Producto p ON p.IdProducto=v.IdProducto WHERE v.Activo=1 AND p.Activo=1");return View();}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult Crear(PurchaseForm form){try{int id=svc.Purchase(form,U);TempData["ok"]="Compra registrada como pendiente. Debes recibir mercadería para aumentar el stock.";return RedirectToAction("Detalle",new{id});}catch(Exception ex){TempData["err"]=ex.Message;return RedirectToAction("Crear");}}
 public IActionResult Detalle(int id){ViewBag.Purchase=db.List("SELECT c.*,p.Nombre Proveedor FROM Compra c JOIN Proveedor p ON p.IdProveedor=c.IdProveedor WHERE c.IdCompra=@id",Db.P("@id",id)).FirstOrDefault();if(ViewBag.Purchase==null)return NotFound();ViewBag.Items=db.List("SELECT d.*,p.Nombre,v.SKU FROM DetalleCompra d JOIN ProductoVariante v ON v.IdVariante=d.IdVariante JOIN Producto p ON p.IdProducto=v.IdProducto WHERE d.IdCompra=@id",Db.P("@id",id));return View();}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult Recibir(int id,int detalle,int cantidad){try{if(Convert.ToInt32(db.Scalar("SELECT COUNT(*) FROM DetalleCompra WHERE IdDetalleCompra=@d AND IdCompra=@c",Db.P("@d",detalle),Db.P("@c",id)))==0)throw new InvalidOperationException("Detalle no corresponde a la compra.");svc.Receive(detalle,cantidad,U);TempData["ok"]="Recepción registrada; stock actualizado.";}catch(Exception ex){TempData["err"]=ex.Message;}return RedirectToAction("Detalle",new{id});}
}
